function uniqTerms(cards) {
  const seen = new Set();
  const out = [];
  for (const c of cards) {
    const k = c.term.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(c);
  }
  return out;
}

const TARGET = 280;

function takeN(cards, label) {
  const u = uniqTerms(cards);
  if (u.length < TARGET) {
    throw new Error(`${label}: only ${u.length} unique cards (need ${TARGET})`);
  }
  return u.slice(0, TARGET);
}

const synonyms = takeN(
  BANK.map(([w, syn]) => ({
    term: w,
    explanation: `Synonyms: ${syn}.`,
  })),
  "synonyms",
);

const meanings = takeN(
  BANK.map(([w, , def]) => ({
    term: w,
    explanation: def,
  })),
  "meanings",
);

const antonyms = takeN(
  BANK.map(([w, , , ant]) => ({
    term: w,
    explanation: `Antonyms: ${ant}.`,
  })),
  "antonyms",
);

const out = `/** Auto-generated BBE English flashcards — do not hand-edit; regenerate via scripts/gen-english-flashcards.mjs */
import type { FlashcardSection } from "./flashcards";

export const ENGLISH_FLASHCARD_SECTIONS: FlashcardSection[] = [
  {
    id: "eng-synonyms",
    title: "1. Synonyms",
    cards: ${JSON.stringify(synonyms, null, 2)},
  },
  {
    id: "eng-meanings",
    title: "2. Meanings",
    cards: ${JSON.stringify(meanings, null, 2)},
  },
  {
    id: "eng-antonyms",
    title: "3. Antonyms",
    cards: ${JSON.stringify(antonyms, null, 2)},
  },
];
`;

